async page=>{
 const out={};
 out.newTaskConflict=await page.evaluate(()=>{const list=[];for(const name of ['审计-互斥甲','审计-互斥乙']){CloudTaskWorkspace.clearActiveContext();RouteRuntime.openPrimary('predictive-tasks');CloudTaskWorkspace.start('预外呼');CloudTaskWorkspace.setTenant('TEN-NISSAN-HQ');CloudTaskWorkspace.update('name',name);CloudTaskWorkspace.setResource('skillGroupId','SG-ALI-HQ-SALES');CloudTaskWorkspace.setResource('callerNumberId','NUM-400-8801');CloudTaskWorkspace.update('minAvailableAgentCount','1');const c=CustomerTasks.pendingForTask('TEN-NISSAN-HQ','7522240')[0];CloudTaskWorkspace.toggleCustomer(c.id,true);CloudTaskWorkspace.next();CloudTaskWorkspace.next();CloudTaskWorkspace.next();CloudTaskWorkspace.submit();const t=CloudCallData.tasks.find(t=>t.name===name);list.push(t);}AliCtiDemo.taskControlScenario='success';const first=AliCtiAdapter.controlTask(list[0],'start',true),second=AliCtiAdapter.controlTask(list[1],'start',true);return {tasks:list.map(t=>({id:t.taskId,name:t.name,status:t.status,cnos:t.alictiCreateDraft.fields.cnos,enterpriseId:t.enterpriseId})),first,second};});
 out.inboundPositive=await page.evaluate(()=>{RouteRuntime.openPrimary('inbound-service');const k='alicti-inbound-router-v1',prior=localStorage.getItem(k);const clean=JSON.parse(prior);clean.pending=[];localStorage.setItem(k,JSON.stringify(clean));try{const key=AliCtiInbound.context(),res=AliCtiInbound.resources(),out=[];for(const type of [1,2,3]){const input={name:'审计接听方式'+type,routerType:type,active:1,priority:200+type,description:'审计',ruleAreaProperty:'021;010',ruleTimeProperty:'',ruleTrunkProperty:'',...(type===1?{ivrId:res.ivrs[0].id}:type===2?{tel:'13800001234'}:{exten:res.extens[0].exten})};const created=AliCtiInbound.save(input,{context:key}),id=created.row?.id;const update=id?AliCtiInbound.save({...input,description:'更新备注'},{context:key,id}):null,pause=id?AliCtiInbound.setActive(id,2,key):null,deleted=id?AliCtiInbound.remove(id,key):null;out.push({type,created,update,pause,deleted});}return out;}finally{localStorage.setItem(k,prior);}});
 out.accounts=await page.evaluate(()=>({accounts:AppState.accounts?.()||CloudCallData.accounts?.map(a=>({accountId:a.accountId,name:a.name})),methods:Object.keys(AppState).filter(k=>/session|login|tenant/i.test(k))}));
 return out;
}
